window.ADVANCED={"s57": {"question": "Bir partiden kontrol örneği kaç farklı biçimde seçilebilir?", "reading": "Sıralı seçimin neden daha çok sonuç ürettiğini karşılaştır.", "limit": "Bu sayma modeli yerine koymadan ve eşit olasılıklı seçim içindir.", "task": "n=12, k=3 yerine k=5 kullan; kombinasyonun neden monoton artmadığını açıkla.", "code": "from math import comb, perm\nn,k=12,3\nprint({'sirasiz':comb(n,k),'sirali':perm(n,k),'oran':perm(n,k)/comb(n,k)})\nks=np.arange(n+1);plt.bar(ks,[comb(n,int(j)) for j in ks]);plt.xlabel('Seçilen birim k');plt.ylabel('Kombinasyon sayısı')\nassert perm(n,k)==comb(n,k)*perm(k,k)", "id": "s57", "module": 14, "title": "Permütasyon ve kombinasyon", "output": "{'sirasiz': 220, 'sirali': 1320, 'oran': 6.0}\n", "image": "advanced/s57.png", "notebook": "advanced/konu_15.ipynb", "script": "advanced/konu_15.py"}, "s58": {"question": "Hacim bilgisi süre tahminini nasıl günceller?", "reading": "Noktaların eğimini ve X=1 için koşullu ortalamayı birlikte oku.", "limit": "İki değişkenli normal modelin koşullu formülü kullanılır; her veri için geçerli değildir.", "task": "Korelasyonu .7’den -.4’e değiştir; marjinal ve koşullu ortalamaları ayır.", "code": "rho=.7;xy=rng.multivariate_normal([0,0],[[1,rho],[rho,1]],600)\nx0=1.;print({'marjinal_EY':0,'kosullu_EY_X1':rho*x0,'kosullu_varyans':1-rho**2})\nplt.scatter(*xy.T,s=10,alpha=.35);plt.plot([-3,3],rho*np.array([-3,3]),c='tab:orange',label='E[Y|X]');plt.xlabel('Standart hacim');plt.ylabel('Standart süre');plt.legend()", "id": "s58", "module": 14, "title": "Ortak, marjinal ve koşullu dağılımlar", "output": "{'marjinal_EY': 0, 'kosullu_EY_X1': 0.7, 'kosullu_varyans': 0.51}\n", "image": "advanced/s58.png", "notebook": "advanced/konu_15.ipynb", "script": "advanced/konu_15.py"}, "s59": {"question": "Log dönüşümü ortalama belirsizliğini nasıl değiştirir?", "reading": "Bootstrap log-ortalama dağılımını delta aralığıyla karşılaştır.", "limit": "Delta yaklaşımı düzgün dönüşüm ve yeterli örneklem ister; log ortalama ile ortalama log farklıdır.", "task": "n=80 yerine n=15 kullan ve yaklaşım farkını yorumla.", "code": "x=rng.lognormal(2,.5,80);mu=x.mean();se=x.std(ddof=1)/np.sqrt(len(x));delta=se/mu\nboot=np.log(rng.choice(x,(2000,len(x))).mean(axis=1));print({'log_ortalama':np.log(mu),'delta_SE':delta,'bootstrap_SE':boot.std(ddof=1)})\nplt.hist(boot,bins=30);plt.axvline(np.log(mu)-1.96*delta,c='tab:orange');plt.axvline(np.log(mu)+1.96*delta,c='tab:orange');plt.xlabel('log(örneklem ortalaması)');plt.ylabel('Tekrar sayısı')", "id": "s59", "module": 14, "title": "Değişken dönüşümleri ve delta yöntemi", "output": "{'log_ortalama': np.float64(2.180661303807213), 'delta_SE': np.float64(0.05412841990426161), 'bootstrap_SE': np.float64(0.053410959811427974)}\n", "image": "advanced/s59.png", "notebook": "advanced/konu_15.ipynb", "script": "advanced/konu_15.py"}, "s60": {"question": "Daha çok veri hangi oynaklığı azaltır?", "reading": "n arttığında sapma olasılığı ile Chebyshev üst sınırını karşılaştır.", "limit": "Sınır gevşek olabilir; bağımsız sonlu varyanslı üstel veri kullanılır.", "task": "Sapma eşiğini .3 yerine .15 yap; gerekli n üzerindeki etkiyi açıkla.", "code": "ns=np.array([5,10,20,50,100,200]);eps=.3\nobserved=[np.mean(np.abs(rng.exponential(1,(3000,int(n))).mean(axis=1)-1)>=eps) for n in ns]\nbound=np.minimum(1,1/(ns*eps**2));print(pd.DataFrame({'n':ns,'gozlenen':observed,'Chebyshev':bound}))\nplt.plot(ns,observed,'o-',label='Simülasyon');plt.plot(ns,bound,'o-',label='Üst sınır');plt.xlabel('n');plt.ylabel('P(|ortalama−1|≥ε)');plt.legend()", "id": "s60", "module": 14, "title": "Büyük sayılar yasası ve olasılık sınırları", "output": "     n  gozlenen  Chebyshev\n0    5  0.493000   1.000000\n1   10  0.315333   1.000000\n2   20  0.183000   0.555556\n3   50  0.036000   0.222222\n4  100  0.003667   0.111111\n5  200  0.000000   0.055556\n", "image": "advanced/s60.png", "notebook": "advanced/konu_15.ipynb", "script": "advanced/konu_15.py"}, "s61": {"question": "Yanlı ama daha kararlı tahmin bazen daha iyi olabilir mi?", "reading": "Sapma ve varyansın toplamının MSE’ye katkısını oku.", "limit": "Sonuç seçilmiş simülasyon evrenine aittir; tek kazanan evrensel değildir.", "task": "Gerçek ortalamayı 1’den 0’a değiştir; küçültmenin zararını/kazancını yeniden değerlendir.", "code": "truth=1.;samples=rng.normal(truth,2,(4000,8));raw=samples.mean(axis=1);shrink=.65*raw\nrows=[]\nfor name,v in [('Ortalama',raw),('0 yönüne küçültme',shrink)]:\n bias=v.mean()-truth;var=v.var();mse=np.mean((v-truth)**2);rows.append([name,bias,var,mse]);assert abs(mse-bias**2-var)<1e-10\nprint(pd.DataFrame(rows,columns=['tahmin','yanlilik','varyans','MSE']));plt.hist(raw,bins=35,alpha=.5,label='Ortalama');plt.hist(shrink,bins=35,alpha=.5,label='Küçültme');plt.axvline(truth,c='black');plt.legend();plt.xlabel('Tahmin');plt.ylabel('Tekrar sayısı')", "id": "s61", "module": 15, "title": "Yanlılık, tutarlılık ve ortalama kare hata", "output": "              tahmin  yanlilik   varyans       MSE\n0           Ortalama  0.007149  0.495353  0.495404\n1  0 yönüne küçültme -0.345353  0.209287  0.328556\n", "image": "advanced/s61.png", "notebook": "advanced/konu_16.ipynb", "script": "advanced/konu_16.py"}, "s62": {"question": "Sayım verisinde MLE ve momentler nerede buluşur?", "reading": "Olabilirlik tepesinin örneklem ortalamasıyla çakışmasını izle.", "limit": "Poisson modeli ortak hız ve uygun maruziyet varsayar; aşırı saçılmayı çözmez.", "task": "Üretim hızını 4’ten 9’a değiştir; hız tahminini ve eğriyi yeniden hesapla.", "code": "x=rng.poisson(4,80);mle=x.mean();grid=np.linspace(.1,9,180);ll=np.array([stats.poisson.logpmf(x,v).sum() for v in grid])\nprint({'MLE':mle,'momentler':x.mean(),'n':len(x)})\nplt.plot(grid,np.exp(ll-ll.max()));plt.axvline(mle,c='tab:orange');plt.xlabel('Poisson hız λ');plt.ylabel('Göreli olabilirlik')", "id": "s62", "module": 15, "title": "En çok olabilirlik ve momentler yöntemi", "output": "{'MLE': np.float64(3.9125), 'momentler': np.float64(3.9125), 'n': 80}\n", "image": "advanced/s62.png", "notebook": "advanced/konu_16.ipynb", "script": "advanced/konu_16.py"}, "s63": {"question": "Olabilirlik oranı ile Wald yaklaşımı aynı sonucu verir mi?", "reading": "İki aralığın özellikle küçük sayımlarda ayrılabildiğini gör.", "limit": "Wilks χ² ve Wald yaklaşımları sınırda/küçük örneklemde zayıflayabilir.", "task": "k=7,n=40 yerine k=1,n=10 kullan; simetrik aralığın sınır sorununu incele.", "code": "k,n=7,40;p=k/n;grid=np.linspace(.0001,.9999,1000);ll=stats.binom.logpmf(k,n,grid);best=stats.binom.logpmf(k,n,p);lr=2*(best-ll);ok=grid[lr<=stats.chi2.ppf(.95,1)]\ninfo=n/(p*(1-p));print({'MLE':p,'Fisher_bilgi':info,'Wald':(p-1.96/np.sqrt(info),p+1.96/np.sqrt(info)),'LR_profil':(ok.min(),ok.max())})\nplt.plot(grid,lr);plt.axhline(stats.chi2.ppf(.95,1),c='tab:orange');plt.ylim(0,12);plt.xlabel('p');plt.ylabel('2 log olabilirlik farkı')", "id": "s63", "module": 15, "title": "Fisher bilgisi ve olabilirlik oranı", "output": "{'MLE': 0.175, 'Fisher_bilgi': 277.0562770562771, 'Wald': (np.float64(0.05724697456116043), np.float64(0.2927530254388395)), 'LR_profil': (np.float64(0.08016406406406408), np.float64(0.3103482482482483))}\n", "image": "advanced/s63.png", "notebook": "advanced/konu_16.ipynb", "script": "advanced/konu_16.py"}, "s64": {"question": "Daha esnek modelin daha iyi uyumu neye mal olur?", "reading": "AIC/BIC ile ayrı test hatasını aynı dereceler için karşılaştır.", "limit": "Bilgi kriterleri aynı yanıt/olabilirlik ve uygun parametre sayısıyla karşılaştırılır; test seti model seçmek için tüketilmez.", "task": "n=100 yerine n=30 kullan; yüksek derecenin cezasını ve test hatasını karşılaştır.", "code": "x=np.linspace(-2,2,100);y=2+x+.7*x*x+rng.normal(0,1,len(x));xt=rng.uniform(-2,2,500);yt=2+xt+.7*xt*xt+rng.normal(0,1,500);rows=[]\nfor degree in range(1,7):\n model=sm.OLS(y,np.vander(x,degree+1,increasing=True)).fit();pred=model.predict(np.vander(xt,degree+1,increasing=True));rows.append([degree,model.aic,model.bic,mean_squared_error(yt,pred)])\ntab=pd.DataFrame(rows,columns=['derece','AIC','BIC','test_MSE']);print(tab);plt.plot(tab.derece,tab.AIC,label='AIC');plt.plot(tab.derece,tab.BIC,label='BIC');plt.xlabel('Derece');plt.ylabel('Bilgi kriteri');plt.legend()", "id": "s64", "module": 15, "title": "AIC, BIC ve model seçimi", "output": "   derece         AIC         BIC  test_MSE\n0       1  312.586065  317.796405  1.726379\n1       2  263.138778  270.954289  1.028556\n2       3  260.656314  271.076995  1.055818\n3       4  262.028073  275.053924  1.060199\n4       5  262.396361  278.027382  1.065489\n5       6  264.395994  282.632185  1.065357\n", "image": "advanced/s64.png", "notebook": "advanced/konu_16.ipynb", "script": "advanced/konu_16.py"}, "s65": {"question": "Bağımsız vardiya ile aynı kişilerin değişimi neden farklı test ister?", "reading": "Eşleştirilmiş çizgilerin yönüyle grup histogramını ayır.", "limit": "Wilcoxon sıfır fark ve simetri koşulları; Mann–Whitney dağılımsal hedefi korunmalı.", "task": "Sonra sütununu rastgele karıştır; eşleştirmenin etkisini açıklayarak iki testi yeniden çalıştır.", "code": "a=rng.lognormal(2,.35,30);b=a-rng.normal(.8,.6,30);ind=rng.lognormal(2,.35,35)\nprint({'Wilcoxon_esli':stats.wilcoxon(a,b).pvalue,'Mann_Whitney_bagimsiz':stats.mannwhitneyu(a,ind,method='asymptotic').pvalue})\nplt.plot([0,1],np.vstack([a,b]),alpha=.35);plt.xticks([0,1],['Önce','Sonra']);plt.ylabel('Aynı birimde süre')", "id": "s65", "module": 16, "title": "Mann–Whitney ve Wilcoxon", "output": "{'Wilcoxon_esli': np.float64(6.146728992462158e-08), 'Mann_Whitney_bagimsiz': np.float64(0.10696593230130519)}\n", "image": "advanced/s65.png", "notebook": "advanced/konu_17.ipynb", "script": "advanced/konu_17.py"}, "s66": {"question": "Üç bağımsız grup ile üç tekrarlı ölçümü nasıl ayırırım?", "reading": "Aynı birimin üç ölçümü arasındaki bağı koru.", "limit": "Kruskal ve Friedman aynı deney tasarımını test etmez; genel p hangi çiftin farklı olduğunu söylemez.", "task": "Birimin ortak etkisini artır; Friedman ile bağımsız yaklaşımın farkını açıkla.", "code": "base=rng.normal(10,3,25);a=base+rng.normal(0,1,25);b=base+1+rng.normal(0,1,25);c=base+2+rng.normal(0,1,25)\nprint({'Friedman_tekrarli':stats.friedmanchisquare(a,b,c).pvalue,'Kruskal_bagimsiz_ornek':stats.kruskal(rng.normal(10,2,25),rng.normal(11,2,25),rng.normal(12,2,25)).pvalue})\nplt.boxplot([a,b,c],tick_labels=['A','B','C']);plt.ylabel('Ölçüm');plt.xlabel('Tekrarlı yöntem')", "id": "s66", "module": 16, "title": "Kruskal–Wallis ve Friedman", "output": "{'Friedman_tekrarli': np.float64(0.00016995106759902634), 'Kruskal_bagimsiz_ornek': np.float64(0.00012229251283106288)}\n", "image": "advanced/s66.png", "notebook": "advanced/konu_17.ipynb", "script": "advanced/konu_17.py"}, "s67": {"question": "Uç süreyi silmeden tipik performansı nasıl raporlarım?", "reading": "Ortalama, medyan ve kırpılmış ortalamanın aykırılığa tepkisini karşılaştır.", "limit": "Kırpma önceden belirlenmeli; geçerli kuyruk maliyetini ortadan kaldırdığı varsayılmamalı.", "task": "Son 80 dakikalık kaydı 800 yap; her özetin değişimini yaz.", "code": "x=np.r_[rng.normal(10,1,39),80];trim=.1;med=np.median(x);mad=stats.median_abs_deviation(x,scale='normal');print({'ortalama':x.mean(),'medyan':med,'kirpilmis':stats.trim_mean(x,trim),'MAD_normal_olcek':mad})\nplt.hist(x,bins=25);plt.axvline(x.mean(),label='Ortalama',c='tab:orange');plt.axvline(med,label='Medyan',c='tab:green');plt.xlabel('Süre');plt.ylabel('Kayıt');plt.legend()", "id": "s67", "module": 16, "title": "Robust özetler ve kırpılmış ortalama", "output": "{'ortalama': np.float64(12.035374365028673), 'medyan': np.float64(10.291925442802448), 'kirpilmis': np.float64(10.314288079351364), 'MAD_normal_olcek': np.float64(0.7555055715297753)}\n", "image": "advanced/s67.png", "notebook": "advanced/konu_17.ipynb", "script": "advanced/konu_17.py"}, "s68": {"question": "Fark bulamamak yerine eşdeğerliği nasıl sınarım?", "reading": "%90 fark aralığının önceden seçilmiş ±Δ sınırları içinde kalıp kalmadığını oku.", "limit": "İki tek yönlü test α=.05 ile eşdeğerlik sınırı önceden seçilir; aşağı kalmama tek yönlü başka hedeftir.", "task": "Eşdeğerlik marjını 1’den .3’e indir ve kararın değişmesini açıkla.", "code": "d=rng.normal(.1,1.2,50);delta=1.;se=stats.sem(d);df=len(d)-1\np_lower=stats.t.sf((d.mean()+delta)/se,df);p_upper=stats.t.cdf((d.mean()-delta)/se,df);ci=stats.t.interval(.90,df,loc=d.mean(),scale=se)\nprint({'fark':d.mean(),'TOST_p':max(p_lower,p_upper),'CI90':ci,'esdeger':bool(max(p_lower,p_upper)<.05),'asagi_kalmama_ust_sinir_p':p_upper})\nplt.errorbar([d.mean()],[1],xerr=[[d.mean()-ci[0]],[ci[1]-d.mean()]],fmt='o');plt.axvline(-delta,c='tab:orange');plt.axvline(delta,c='tab:orange');plt.yticks([]);plt.xlabel('Önce−sonra farkı')", "id": "s68", "module": 16, "title": "Eşdeğerlik ve aşağı kalmama testleri", "output": "{'fark': np.float64(0.4554990894324354), 'TOST_p': np.float64(0.0010695699081233743), 'CI90': (np.float64(0.17390051504864895), np.float64(0.7370976638162217)), 'esdeger': True, 'asagi_kalmama_ust_sinir_p': np.float64(0.0010695699081233743)}\n", "image": "advanced/s68.png", "notebook": "advanced/konu_17.ipynb", "script": "advanced/konu_17.py"}, "s69": {"question": "İş yükü etkisi vardiyaya göre değişiyor mu?", "reading": "İki vardiya doğrusunun farklı eğimlerini karşılaştır.", "limit": "Etkileşim koşullu ilişkiyi gösterir; randomizasyon olmadan nedensellik kurulmaz.", "task": "Etkileşim katsayısını 1.2’den 0’a indir; modelde ve grafikte ne değiştiğini yaz.", "code": "x=rng.uniform(0,5,180);shift=rng.integers(0,2,180);y=3+2*x+2*shift+1.2*x*shift+.2*x*x+rng.normal(0,1,180);d=pd.DataFrame({'x':x,'vardiya':shift,'y':y});fit=smf.ols('y ~ x * vardiya + I(x**2)',d).fit();print(fit.params.round(3));print('Etkileşim CI:',fit.conf_int().loc['x:vardiya'].round(3).tolist())\nfor g in [0,1]:\n xx=np.linspace(0,5,80);plt.scatter(x[shift==g],y[shift==g],s=10,alpha=.25);plt.plot(xx,fit.predict(pd.DataFrame({'x':xx,'vardiya':g})),label=f'Vardiya {g}')\nplt.xlabel('Hacim');plt.ylabel('Süre');plt.legend()", "id": "s69", "module": 17, "title": "Etkileşimler ve polinom regresyon", "output": "Intercept    2.548\nx            2.561\nvardiya      1.956\nx:vardiya    1.231\nI(x ** 2)    0.097\ndtype: float64\nEtkileşim CI: [1.017, 1.446]\n", "image": "advanced/s69.png", "notebook": "advanced/konu_18.ipynb", "script": "advanced/konu_18.py"}, "s70": {"question": "Daha uzun maruziyet daha çok hatayı açıklıyor mu?", "reading": "Aynı x için sayım yerine maruziyet başına oranı karşılaştır.", "limit": "Offset log(maruziyet) katsayısı 1’e sabittir. Negatif binom modeli aşırı saçılma için ayrıca gerekçelendirilir.", "task": "Maruziyetleri iki katına çıkar; oran ile beklenen sayımı ayır.", "code": "x=rng.normal(size=250);exposure=rng.uniform(.5,3,250);mu=exposure*np.exp(.5+.6*x);y=rng.negative_binomial(3,3/(3+mu));X=sm.add_constant(x)\npois=sm.GLM(y,X,family=sm.families.Poisson(),offset=np.log(exposure)).fit();nb=sm.NegativeBinomial(y,X,offset=np.log(exposure)).fit(disp=False)\nprint({'Poisson_beta':pois.params.tolist(),'NB_beta_ve_alpha':nb.params.tolist(),'Poisson_Pearson_dispersion':pois.pearson_chi2/pois.df_resid})\norder=np.argsort(x);plt.scatter(x,y/exposure,s=12,alpha=.25,label='Gözlenen oran');plt.plot(x[order],np.exp(X@pois.params)[order],label='Poisson');plt.plot(x[order],np.exp(X@nb.params[:2])[order],label='NB');plt.xlabel('x');plt.ylabel('Olay / maruziyet');plt.legend()", "id": "s70", "module": 17, "title": "Poisson, negatif binom ve maruziyet", "output": "{'Poisson_beta': [0.5426040288889732, 0.6184653966642888], 'NB_beta_ve_alpha': [0.547243668326864, 0.6052450989344944, 0.3736596116198779], 'Poisson_Pearson_dispersion': np.float64(2.32491160034765)}\n", "image": "advanced/s70.png", "notebook": "advanced/konu_18.ipynb", "script": "advanced/konu_18.py"}, "s71": {"question": "Az kayıtlı deponun ortalamasına ne kadar güvenmeliyim?", "reading": "Ham grup ortalamalarıyla karma model tahminlerini karşılaştır.", "limit": "Rastgele kesişim modeli grupların ortak dağılımını varsayar; ML/REML ve grup tasarımı önemlidir.", "task": "İlk deponun n değerini 5’ten 50’ye çıkar; küçültmenin nasıl değiştiğini incele.", "code": "rows=[]\nfor g,n in enumerate([5,8,12,16,20,24,30,40]):\n u=rng.normal(0,2)\n for j in range(n):rows.append([str(g),10+u+rng.normal(0,3)])\nd=pd.DataFrame(rows,columns=['depo','sure']);fit=smf.mixedlm('sure ~ 1',d,groups=d.depo).fit(reml=True,method='powell',disp=False);raw=d.groupby('depo').sure.mean();pooled=np.array([fit.fe_params.iloc[0]+float(fit.random_effects[g].iloc[0]) for g in raw.index]);print({'genel_ortalama':float(fit.fe_params.iloc[0]),'grup_varyansi':float(fit.cov_re.iloc[0,0]),'hata_varyansi':float(fit.scale)})\nplt.plot(raw.index,raw,'o',label='Ham');plt.plot(raw.index,pooled,'o',label='Kısmi havuzlama');plt.xlabel('Depo');plt.ylabel('Beklenen süre');plt.legend()", "id": "s71", "module": 17, "title": "Karma etkili modeller ve kısmi havuzlama", "output": "{'genel_ortalama': 10.379004704382114, 'grup_varyansi': 2.192024162969332, 'hata_varyansi': 7.739394878555071}\n", "image": "advanced/s71.png", "notebook": "advanced/konu_18.ipynb", "script": "advanced/konu_18.py"}, "s72": {"question": "Ortalama süre iyi görünürken üst hizmet kuyruğu ne oluyor?", "reading": "Koşullu medyan ve .9 kantil çizgisini aynı noktalarda oku.", "limit": "Kantil katsayısı koşullu kantile aittir; nedensellik veya tekil tahmin garantisi değildir.", "task": "Hata ölçeğinin x ile artışını kaldır; kantil eğimlerinin değişimini açıkla.", "code": "x=rng.uniform(0,8,250);y=5+2*x+rng.normal(size=len(x))*(1+.5*x);X=sm.add_constant(x);grid=np.linspace(0,8,100)\nfor q in [.5,.9]:\n fit=sm.QuantReg(y,X).fit(q=q,max_iter=3000);print('Kantil',q,'katsayılar',fit.params.round(3));plt.plot(grid,fit.predict(sm.add_constant(grid)),label=f'q={q}')\nplt.scatter(x,y,s=10,alpha=.2);plt.xlabel('Hacim');plt.ylabel('Süre');plt.legend()", "id": "s72", "module": 17, "title": "Kantil regresyon ve esnek eğriler", "output": "Kantil 0.5 katsayılar [4.825 2.131]\nKantil 0.9 katsayılar [5.88  2.817]\n", "image": "advanced/s72.png", "notebook": "advanced/konu_18.ipynb", "script": "advanced/konu_18.py"}, "s73": {"question": "Az gözlemli grubun oranını ortak önselle nasıl güncellerim?", "reading": "Beta sonsallarının genişliği ile örneklem büyüklüğünü eşleştir.", "limit": "Burada üst düzey Beta parametreleri sabittir; onların belirsizliğini öğrenen tam hiyerarşik model değildir.", "task": "Önseli Beta(2,18) yerine Beta(1,1) yap; küçük grupta etkiyi açıkla.", "code": "a,b=2,18;groups=[(1,8),(10,80),(30,200)];p=np.linspace(.001,.999,400)\nfor k,n in groups:\n post=stats.beta(a+k,b+n-k);print({'k':k,'n':n,'ham':k/n,'sonsal':post.mean(),'CI95':post.ppf([.025,.975]).tolist()});plt.plot(p,post.pdf(p),label=f'{k}/{n}')\nplt.xlabel('Grup olay olasılığı');plt.ylabel('Sonsal yoğunluk');plt.legend()", "id": "s73", "module": 18, "title": "Eşlenik önseller ve hiyerarşik Bayes", "output": "{'k': 1, 'n': 8, 'ham': 0.125, 'sonsal': np.float64(0.10714285714285714), 'CI95': [0.02352745438085398, 0.24289834684562717]}\n{'k': 10, 'n': 80, 'ham': 0.125, 'sonsal': np.float64(0.12), 'CI95': [0.06422779037888428, 0.19011643481938723]}\n{'k': 30, 'n': 200, 'ham': 0.15, 'sonsal': np.float64(0.14545454545454545), 'CI95': [0.10214110448001647, 0.19486687037410083]}\n", "image": "advanced/s73.png", "notebook": "advanced/konu_19.ipynb", "script": "advanced/konu_19.py"}, "s74": {"question": "Yüksek kabul oranı iyi karışma anlamına gelir mi?", "reading": "İzleri ve klasik split R-hat değerini adım boyuna göre karşılaştır.", "limit": "Random-walk öğretim uygulaması modern rank-normalize R-hat ve HMC tanılarının yerine geçmez.", "task": "step=.12 yerine .005 kullan; kabul ve zincirler arası farkı birlikte yorumla.", "code": "a,b,step=5,9,.12;chains=[];accepted=0\nfor start in [.1,.35,.65,.9]:\n z=start;out=[]\n for i in range(2400):\n  proposal=z+rng.normal(0,step)\n  if 0<proposal<1 and np.log(rng.uniform())<stats.beta.logpdf(proposal,a,b)-stats.beta.logpdf(z,a,b):z=proposal;accepted+=1\n  if i>=800:out.append(z)\n chains.append(out)\nc=np.array(chains);split=c.reshape(8,800);W=split.var(axis=1,ddof=1).mean();B=800*split.mean(axis=1).var(ddof=1);rhat=np.sqrt(((799/800)*W+B/800)/W)\nprint({'kabul':accepted/9600,'klasik_split_Rhat':rhat,'cekim_ortalama':c.mean(),'analitik':a/(a+b)})\nplt.plot(c.T[::8],alpha=.65);plt.xlabel('Saklanan çekim / 8');plt.ylabel('p')", "id": "s74", "module": 18, "title": "MCMC ve yakınsama tanıları", "output": "{'kabul': 0.7175, 'klasik_split_Rhat': np.float64(1.00263877554605), 'cekim_ortalama': np.float64(0.3536931887772823), 'analitik': 0.35714285714285715}\n", "image": "advanced/s74.png", "notebook": "advanced/konu_19.ipynb", "script": "advanced/konu_19.py"}, "s75": {"question": "Model gözlenen hata sayısını yeniden üretebiliyor mu?", "reading": "Gözlenen istatistiği sonsal öngörü histogramıyla karşılaştır.", "limit": "Sonsal öngörü kontrolü model uygunluğuna bakar; kullanılan veriden bağımsız doğrulama değildir.", "task": "n=100,k=12 değerini değiştir; öngörü ile parametre aralığını ayır.", "code": "k,n=12,100;p=rng.beta(2+k,18+n-k,4000);rep=rng.binomial(n,p);print({'yeni_sayim_ortalama':rep.mean(),'ongoru_95':np.quantile(rep,[.025,.975]).tolist(),'gozlenen':k,'parametre_95':np.quantile(p,[.025,.975]).tolist()})\nplt.hist(rep,bins=np.arange(rep.max()+2)-.5);plt.axvline(k,c='tab:orange',label='Gözlenen');plt.xlabel('Yeni 100 kayıtta hata sayısı');plt.ylabel('Tekrar');plt.legend()", "id": "s75", "module": 18, "title": "Sonsal öngörü kontrolü", "output": "{'yeni_sayim_ortalama': np.float64(11.66625), 'ongoru_95': [4.0, 21.0], 'gozlenen': 12, 'parametre_95': [0.0667689009431097, 0.17832741200793395]}\n", "image": "advanced/s75.png", "notebook": "advanced/konu_19.ipynb", "script": "advanced/konu_19.py"}, "s76": {"question": "Önsel ve hata maliyeti kararı nasıl değiştirir?", "reading": "Farklı önsellerde sonsal ve BF10 değerini karşılaştır.", "limit": "Bayes faktörü belirtilen nokta H0 ile Beta alternatifini karşılaştırır; önsele duyarlıdır.", "task": "H0 oranını .1’den .2’ye değiştir; maliyet eşiğini ayrı değerlendir.", "code": "k,n,p0=18,100,.1;rows=[]\nfor a,b in [(1,1),(2,18),(10,90)]:\n logBF=special.betaln(a+k,b+n-k)-special.betaln(a,b)-k*np.log(p0)-(n-k)*np.log1p(-p0);prob=stats.beta.sf(p0,a+k,b+n-k);rows.append([f'{a},{b}',prob,np.exp(logBF)])\nprint(pd.DataFrame(rows,columns=['Beta_onsel','P_p_buyuk_H0','BF10']));C_FP,C_FN=2,10;print('Pozitif karar eşiği:',C_FP/(C_FP+C_FN))\nplt.bar([r[0] for r in rows],[r[1] for r in rows]);plt.ylim(0,1);plt.xlabel('Önsel');plt.ylabel('P(p > H0 | veri)')", "id": "s76", "module": 18, "title": "Duyarlılık, karar eşiği ve Bayes faktörü", "output": "  Beta_onsel  P_p_buyuk_H0      BF10\n0        1,1      0.994877  1.824554\n1       2,18      0.985537  3.935736\n2      10,90      0.958859  3.016920\nPozitif karar eşiği: 0.16666666666666666\n", "image": "advanced/s76.png", "notebook": "advanced/konu_19.ipynb", "script": "advanced/konu_19.py"}, "s77": {"question": "Tahmin artıklarında zaman bağımlılığı kaldı mı?", "reading": "AR(1) serisinin ACF ve PACF desenini incele.", "limit": "Gecikme bantları yaklaşık ve çoklu bakış içerir; beyaz gürültü testi model doğruluğunu kanıtlamaz.", "task": "AR katsayısını .7’den 0’a değiştir; Ljung–Box ve grafiği birlikte oku.", "code": "from statsmodels.tsa.stattools import acf,pacf\nfrom statsmodels.stats.diagnostic import acorr_ljungbox\nx=np.zeros(240)\nfor t in range(1,len(x)):x[t]=.7*x[t-1]+rng.normal()\na=acf(x,nlags=16);p=pacf(x,nlags=16);print(acorr_ljungbox(x,lags=[8,16],return_df=True));plt.plot(range(1,17),a[1:],'o-',label='ACF');plt.plot(range(1,17),p[1:],'o-',label='PACF');plt.axhline(0,c='black',lw=.7);plt.xlabel('Gecikme');plt.ylabel('Korelasyon');plt.legend()", "id": "s77", "module": 19, "title": "ACF, PACF ve artık beyaz gürültüsü", "output": "       lb_stat     lb_pvalue\n8   325.696185  1.384184e-65\n16  329.306600  2.110034e-60\n", "image": "advanced/s77.png", "notebook": "advanced/konu_20.ipynb", "script": "advanced/konu_20.py"}, "s78": {"question": "Süreçte kalıcı seviye değişimini nasıl ararım?", "reading": "Tek kırılmalı en küçük kareler taramasını zaman serisinde oku.", "limit": "Bu eğitim taraması bir kırılma varsayar; taranmış en iyi tarih için saf p hesaplamak geçersizdir.", "task": "Değişim büyüklüğünü 3’ten .5’e indir; seçilen tarihin kararlılığını tartış.", "code": "x=np.r_[rng.normal(10,1,80),rng.normal(13,1,80)];candidates=np.arange(20,len(x)-20);loss=np.array([((x[:k]-x[:k].mean())**2).sum()+((x[k:]-x[k:].mean())**2).sum() for k in candidates]);best=int(candidates[loss.argmin()]);print({'secilen_kirilma':best,'once':x[:best].mean(),'sonra':x[best:].mean()})\nplt.plot(x,label='Ölçüm');plt.axvline(best,c='tab:orange',label='Tarama minimumu');plt.xlabel('Zaman');plt.ylabel('Süreç seviyesi');plt.legend()", "id": "s78", "module": 19, "title": "Değişim noktaları ve yapısal kırılmalar", "output": "{'secilen_kirilma': 81, 'once': np.float64(10.17529694688642), 'sonra': np.float64(12.966127059893957)}\n", "image": "advanced/s78.png", "notebook": "advanced/konu_20.ipynb", "script": "advanced/konu_20.py"}, "s79": {"question": "Gürültülü ölçümde gizli seviyeyi nasıl izlerim?", "reading": "Ölçüm, gerçek simülasyon seviyesi ve filtre tahminini ayır.", "limit": "Yerel seviye Kalman modeli Q/R sabit kabul eder; geleceği kullanan smoother uygulanmaz.", "task": "Q=.08 yerine .8 kullan; tepki hızı ile oynaklık dengesini açıkla.", "code": "Q,R=.08,1.;true=np.cumsum(rng.normal(0,np.sqrt(Q),120));obs=true+rng.normal(0,np.sqrt(R),120);m,P=0.,10.;est=[];unc=[]\nfor y in obs:\n P+=Q;K=P/(P+R);m+=K*(y-m);P=(1-K)*P;est.append(m);unc.append(P)\nest=np.array(est);sd=np.sqrt(unc);print({'olcum_RMSE':np.sqrt(np.mean((obs-true)**2)),'filtre_RMSE':np.sqrt(np.mean((est-true)**2))})\nplt.plot(obs,alpha=.25,label='Ölçüm');plt.plot(true,label='Gerçek seviye');plt.plot(est,label='Filtre');plt.fill_between(range(len(est)),est-1.96*sd,est+1.96*sd,alpha=.15);plt.xlabel('Zaman');plt.ylabel('Seviye');plt.legend()", "id": "s79", "module": 19, "title": "Durum uzayı ve Kalman filtresi", "output": "{'olcum_RMSE': np.float64(1.0186924953419716), 'filtre_RMSE': np.float64(0.45911919785522864)}\n", "image": "advanced/s79.png", "notebook": "advanced/konu_20.ipynb", "script": "advanced/konu_20.py"}, "s80": {"question": "Bağlı serileri ve toplamı tutarlı nasıl tahmin ederim?", "reading": "VAR tahminlerini aynı test döneminde son değer tabanıyla karşılaştır.", "limit": "VAR(1) ve bottom-up toplam örneği; genel hiyerarşi uzlaştırması veya nedensel yön çıkarımı değildir.", "task": "Çapraz etkiyi .3’ten 0’a indir; taban modeline göre kazancı incele.", "code": "from statsmodels.tsa.api import VAR\nx=np.zeros((220,2));A=np.array([[.65,.3],[.1,.55]])\nfor t in range(1,len(x)):x[t]=A@x[t-1]+rng.normal(size=2)\ntrain,test=x[:180],x[180:];fit=VAR(train).fit(1);pred=fit.forecast(train[-1:],len(test));naive=np.repeat(train[-1:],len(test),axis=0);print({'VAR_MSE':mean_squared_error(test,pred),'son_deger_MSE':mean_squared_error(test,naive),'toplam_MSE':mean_squared_error(test.sum(axis=1),pred.sum(axis=1))})\nplt.plot(test.sum(axis=1),label='Gerçek toplam');plt.plot(pred.sum(axis=1),label='Bottom-up VAR toplam');plt.xlabel('Test zamanı');plt.ylabel('İki serinin toplamı');plt.legend()", "id": "s80", "module": 19, "title": "Çoklu seriler ve hiyerarşik tahmin", "output": "{'VAR_MSE': 2.8534877404608547, 'son_deger_MSE': 3.0656484193778137, 'toplam_MSE': 7.6489254520351455}\n", "image": "advanced/s80.png", "notebook": "advanced/konu_20.ipynb", "script": "advanced/konu_20.py"}, "s81": {"question": "Bir durumdan diğerine geçiş uzun dönemi nasıl belirler?", "reading": "Başlangıç etkisinin durağan dağılıma yaklaşmasını izle.", "limit": "Sabit geçiş matrisi ve uygun ergodiklik gerekir; her Markov zinciri tek durağan limite gitmez.", "task": "İlk satırı [.9,.1] yap; uzun dönem ve yakınsama hızını karşılaştır.", "code": "P=np.array([[.8,.2],[.3,.7]]);dist=np.array([1.,0.]);history=[dist.copy()]\nfor t in range(35):dist=dist@P;history.append(dist.copy())\nA=np.vstack([P.T-np.eye(2),np.ones(2)]);stationary=np.linalg.lstsq(A,[0,0,1],rcond=None)[0];assert np.allclose(stationary@P,stationary)\nprint({'duragan':stationary.tolist(),'35_adim':dist.tolist()});plt.plot(history);plt.xlabel('Adım');plt.ylabel('Durum olasılığı');plt.legend(['Normal','Yoğun'])", "id": "s81", "module": 20, "title": "Markov zincirleri ve durağan dağılım", "output": "{'duragan': [0.5999999999999999, 0.40000000000000013], '35_adim': [0.600000000011642, 0.39999999998835867]}\n", "image": "advanced/s81.png", "notebook": "advanced/konu_21.ipynb", "script": "advanced/konu_21.py"}, "s82": {"question": "Kullanımı yükseltmek beklemeyi ne kadar artırır?", "reading": "M/M/1 eğrisindeki doğrusal olmayan artışı oku.", "limit": "Poisson geliş, üstel hizmet, tek sunucu ve λ<μ varsayılır; W saat birimindedir.", "task": "Hizmet hızını 10’dan 12’ye çıkar; aynı gelişte bekleme kazancını hesapla.", "code": "mu=10.;lam=np.linspace(1,9.8,150);W=1/(mu-lam);Wq=lam/(mu*(mu-lam));l=8.;print({'rho':l/mu,'W_dakika':60/(mu-l),'L':l/(mu-l),'Little_kontrol':l*1/(mu-l)})\nplt.plot(lam/mu,60*W,label='Sistemde');plt.plot(lam/mu,60*Wq,label='Kuyrukta');plt.xlabel('Kullanım ρ');plt.ylabel('Bekleme · dakika');plt.legend()", "id": "s82", "module": 20, "title": "Kuyruk teorisi ve Little yasası", "output": "{'rho': 0.8, 'W_dakika': 30.0, 'L': 4.0, 'Little_kontrol': 4.0}\n", "image": "advanced/s82.png", "notebook": "advanced/konu_21.ipynb", "script": "advanced/konu_21.py"}, "s83": {"question": "Ortalama kayıp yerine kuyruk riskini nasıl raporlarım?", "reading": "VaR eşiği ile eşiği aşan kayıpların ortalamasını ayır.", "limit": "Tarihsel/sentetik örneklem kuyruğu gelecekte garanti değildir; küçük kuyruk örneklemi kararsızdır.", "task": "α=.95 yerine .99 kullan; kuyruktaki kayıt sayısını mutlaka raporla.", "code": "loss=rng.lognormal(2,1,4000);alpha=.95;var=np.quantile(loss,alpha);tail=loss[loss>=var];es=tail.mean();print({'VaR':var,'ES':es,'kuyruk_n':len(tail)})\nplt.hist(loss,bins=80);plt.axvline(var,c='tab:orange',label='VaR');plt.axvline(es,c='tab:red',label='ES');plt.xlim(0,np.quantile(loss,.997));plt.xlabel('Kayıp');plt.ylabel('Kayıt');plt.legend()", "id": "s83", "module": 20, "title": "Uç değerler, VaR ve beklenen kuyruk kaybı", "output": "{'VaR': np.float64(40.333594072852094), 'ES': np.float64(66.48585914154746), 'kuyruk_n': 200}\n", "image": "advanced/s83.png", "notebook": "advanced/konu_21.ipynb", "script": "advanced/konu_21.py"}, "s84": {"question": "Dağılım kaymasını tek bir ortalamayla görebilir miyim?", "reading": "P ve Q kategorilerinin paylarını KL yönüyle birlikte oku.", "limit": "KL asimetriktir ve Q sıfırken P pozitifse sonsuzdur; kategoriler aynı tanımlanmalı.", "task": "Q’nun ilk payını .2’den .05’e indirip normalize et; iki KL yönünü karşılaştır.", "code": "p=np.array([.6,.3,.1]);q=np.array([.2,.4,.4]);print({'H_P_bit':stats.entropy(p,base=2),'KL_P_Q_bit':stats.entropy(p,q,base=2),'KL_Q_P_bit':stats.entropy(q,p,base=2)})\nx=np.arange(3);plt.bar(x-.18,p,.36,label='P');plt.bar(x+.18,q,.36,label='Q');plt.xticks(x,['A','B','C']);plt.ylabel('Pay');plt.legend()", "id": "s84", "module": 20, "title": "Entropi, KL ve dağılım karşılaştırması", "output": "{'H_P_bit': np.float64(1.295461844238322), 'KL_P_Q_bit': np.float64(0.6264662506490408), 'KL_Q_P_bit': np.float64(0.6490224995673062)}\n", "image": "advanced/s84.png", "notebook": "advanced/konu_21.ipynb", "script": "advanced/konu_21.py"}, "s85": {"question": "Tek atama belirsizliği neden eksik gösterir?", "reading": "Ayrı sonsal çekimlerle tamamlanmış veri setlerinin eğimlerini karşılaştır.", "limit": "IterativeImputer+BayesianRidge sayısal MAR örneğidir; MNAR ve kategorik alanlar ayrıca modellenmeli.", "task": "Eksik payını %25’ten %50’ye çıkar; Rubin toplam varyansındaki payları karşılaştır.", "code": "from sklearn.experimental import enable_iterative_imputer\nfrom sklearn.impute import IterativeImputer\nx=rng.normal(size=250);z=.6*x+rng.normal(size=250);y=1+2*x+z+rng.normal(size=250);data=np.c_[x,z,y];mask=rng.uniform(size=250)<.25;data[mask,0]=np.nan;est=[];vars=[]\nfor seed in range(10):\n complete=IterativeImputer(estimator=BayesianRidge(),sample_posterior=True,random_state=seed,max_iter=10).fit_transform(data);fit=sm.OLS(complete[:,2],sm.add_constant(complete[:,:2])).fit();est.append(fit.params[1]);vars.append(fit.cov_params()[1,1])\nwithin=np.mean(vars);between=np.var(est,ddof=1);total=within+1.1*between;print({'havuz_egim':np.mean(est),'ic_varyans':within,'arasi_varyans':between,'Rubin_SE':np.sqrt(total)})\nplt.plot(range(1,11),est,'o');plt.axhline(np.mean(est),c='tab:orange');plt.xlabel('Atama');plt.ylabel('Tamamlanmış veri eğimi')", "id": "s85", "module": 21, "title": "Çoklu atama ve eksik veri belirsizliği", "output": "{'havuz_egim': np.float64(2.214864798684707), 'ic_varyans': np.float64(0.005447452379679036), 'arasi_varyans': np.float64(0.00035168531318430034), 'Rubin_SE': np.float64(0.07638263038271048)}\n", "image": "advanced/s85.png", "notebook": "advanced/konu_22.ipynb", "script": "advanced/konu_22.py"}, "s86": {"question": "Ağırlıklı anketin 100 kaydı gerçekten 100 birim bilgi mi?", "reading": "Ağırlık yoğunlaştıkça Kish etkin örneklemin düşmesini izle.", "limit": "Kish ESS tek başına tasarım varyansı değildir; küme/katman/FPC için tam anket tasarımı gerekir.", "task": "Son ağırlığı 15’ten 50’ye çıkar; ağırlıklı ortalama ve ESS’yi birlikte raporla.", "code": "y=rng.normal(10,2,100);w=np.r_[np.ones(99),15.];estimate=np.average(y,weights=w);ess=w.sum()**2/(w@w);print({'agirlikli_ortalama':estimate,'ham_n':len(y),'Kish_ESS':ess,'yalniz_agirlik_DEFF':len(y)/ess})\nplt.plot(w,'o');plt.xlabel('Yanıtlayan');plt.ylabel('Anket ağırlığı')", "id": "s86", "module": 21, "title": "Anket ağırlıkları ve etkin örneklem", "output": "{'agirlikli_ortalama': np.float64(9.885769152906457), 'ham_n': 100, 'Kish_ESS': np.float64(40.111111111111114), 'yalniz_agirlik_DEFF': np.float64(2.493074792243767)}\n", "image": "advanced/s86.png", "notebook": "advanced/konu_22.ipynb", "script": "advanced/konu_22.py"}, "s87": {"question": "Gürültülü ölçüm ilişkiyi nasıl zayıflatır?", "reading": "Aynı yanıt için gerçek ve hatalı x eğimlerini karşılaştır.", "limit": "Klasik bağımsız ölçüm hatası senaryosu; gerçek hayatta hata yapısı ve tekrar ölçümler ayrıca gerekir.", "task": "Ölçüm hata sapmasını 1.5’ten .2’ye indir; zayıflamayı incele.", "code": "x=rng.normal(size=1000);y=3*x+rng.normal(size=1000);xm=x+rng.normal(0,1.5,len(x));btrue=stats.linregress(x,y).slope;bmeas=stats.linregress(xm,y).slope\nbaseline=rng.normal(size=1000);first=baseline+rng.normal(size=1000);second=baseline+rng.normal(size=1000);selected=first>np.quantile(first,.9)\nprint({'gercek_x_egim':btrue,'hata_x_egim':bmeas,'secili_ilk_ortalama':first[selected].mean(),'secili_tekrar_ortalama':second[selected].mean()})\nplt.scatter(xm,y,s=8,alpha=.2);grid=np.linspace(-5,5,50);plt.plot(grid,bmeas*grid,c='tab:orange');plt.xlabel('Hatalı x');plt.ylabel('y')", "id": "s87", "module": 21, "title": "Ölçüm hatası ve regresyona dönüş", "output": "{'gercek_x_egim': np.float64(3.0056697818898734), 'hata_x_egim': np.float64(0.8584989199148481), 'secili_ilk_ortalama': np.float64(2.561208675472453), 'secili_tekrar_ortalama': np.float64(1.364782153169744)}\n", "image": "advanced/s87.png", "notebook": "advanced/konu_22.ipynb", "script": "advanced/konu_22.py"}, "s88": {"question": "Varsayım değişince kararım ayakta kalıyor mu?", "reading": "Eksiklerin gözlenenlerden farklı olabileceği senaryoları karşılaştır.", "limit": "Bu delta duyarlılığı MNAR’ı teşhis etmez; makul aralığı alan bilgisi belirler.", "task": "Delta aralığını ±2 yerine ±5 yap; karar eşiği 10’a göre sonucu yaz.", "code": "import hashlib\nobserved=rng.normal(10,2,80);missing_n=20;deltas=np.linspace(-2,2,9);means=[(observed.sum()+missing_n*(observed.mean()+d))/(len(observed)+missing_n) for d in deltas]\nprint(pd.DataFrame({'delta':deltas,'tam_ortalama':means}));print('Veri SHA256:',hashlib.sha256(observed.tobytes()).hexdigest());plt.plot(deltas,means,'o-');plt.axhline(10,c='tab:orange');plt.xlabel('Eksik ortalaması − gözlenen ortalama');plt.ylabel('Duyarlılık ortalaması')", "id": "s88", "module": 21, "title": "Duyarlılık analizi ve yeniden üretilebilirlik", "output": "   delta  tam_ortalama\n0   -2.0      9.930957\n1   -1.5     10.030957\n2   -1.0     10.130957\n3   -0.5     10.230957\n4    0.0     10.330957\n5    0.5     10.430957\n6    1.0     10.530957\n7    1.5     10.630957\n8    2.0     10.730957\nVeri SHA256: 0d243d3fc030e418ff8e457d21b14f6ba3473e28eefcf58e6f115d853dd230ae\n", "image": "advanced/s88.png", "notebook": "advanced/konu_22.ipynb", "script": "advanced/konu_22.py"}, "s89": {"question": "Eğitim başarısı yeni veride ne kadar korunur?", "reading": "Aynı derecelerde eğitim ve bağımsız test hatasını karşılaştır.", "limit": "Tek simülasyon genelleme dağılımını göstermez; test üzerinde derece seçilmez.", "task": "Gürültüyü .3’ten .7’ye çıkar; eğitim ve test farkını açıkla.", "code": "x=rng.uniform(-1,1,40);y=np.sin(3*x)+rng.normal(0,.3,40);xt=rng.uniform(-1,1,500);yt=np.sin(3*xt)+rng.normal(0,.3,500);rows=[]\nfor d in [1,2,4,8,12]:\n m=make_pipeline(PolynomialFeatures(d),Ridge(alpha=.001));m.fit(x[:,None],y);rows.append([d,mean_squared_error(y,m.predict(x[:,None])),mean_squared_error(yt,m.predict(xt[:,None]))])\nt=pd.DataFrame(rows,columns=['derece','egitim','test']);print(t);plt.plot(t.derece,t.egitim,'o-',label='Eğitim');plt.plot(t.derece,t.test,'o-',label='Test');plt.xlabel('Derece');plt.ylabel('MSE');plt.legend()", "id": "s89", "module": 22, "title": "Ampirik risk ve genelleme", "output": "   derece    egitim      test\n0       1  0.149139  0.259512\n1       2  0.143153  0.268318\n2       4  0.055273  0.093369\n3       8  0.051831  0.097354\n4      12  0.051324  0.097734\n", "image": "advanced/s89.png", "notebook": "advanced/konu_23.ipynb", "script": "advanced/konu_23.py"}, "s90": {"question": "Yanlılık ve varyansı tek eğitimden ayırabilir miyim?", "reading": "Aynı evrenden yeniden eğitilmiş modellerin varyansını ölç.", "limit": "Bileşenler gerçek f bilindiği için simülasyonda ayrılır; gerçek veride doğrudan gözlenmez.", "task": "n=30 yerine n=100 yap; model varyansını karşılaştır.", "code": "grid=np.linspace(-1,1,150);truth=np.sin(3*grid);sigma=.3;rows=[]\nfor d in [1,3,8]:\n predictions=[]\n for repeat in range(60):\n  x=rng.uniform(-1,1,30);y=np.sin(3*x)+rng.normal(0,sigma,30);m=make_pipeline(PolynomialFeatures(d),Ridge(alpha=.001));m.fit(x[:,None],y);predictions.append(m.predict(grid[:,None]))\n p=np.array(predictions);bias2=np.mean((p.mean(axis=0)-truth)**2);variance=p.var(axis=0).mean();rows.append([d,bias2,variance,sigma**2])\nt=pd.DataFrame(rows,columns=['derece','yanlilik2','varyans','gurultu']);print(t);plt.bar(t.derece,t.yanlilik2,label='Yanlılık²');plt.bar(t.derece,t.varyans,bottom=t.yanlilik2,label='Varyans');plt.bar(t.derece,t.gurultu,bottom=t.yanlilik2+t.varyans,label='Gürültü');plt.xlabel('Derece');plt.ylabel('Beklenen hata bileşenleri');plt.legend()", "id": "s90", "module": 22, "title": "Yanlılık–varyans ve indirgenemez hata", "output": "   derece  yanlilik2   varyans  gurultu\n0       1   0.170889  0.025430     0.09\n1       3   0.003425  0.013093     0.09\n2       8   0.001112  0.089370     0.09\n", "image": "advanced/s90.png", "notebook": "advanced/konu_23.ipynb", "script": "advanced/konu_23.py"}, "s91": {"question": "Kaçırma maliyeti artarsa eşik ne olmalı?", "reading": "Maliyet eğrisinin minimumunu precision/recall hedefinden ayır.", "limit": "Teorik eşik kalibre olasılık ve sabit maliyet varsayar; burada sentetik olasılıklar üretici modelden bilinir.", "task": "FN maliyetini 10’dan 2’ye indir; teorik ve gözlenen eşikleri karşılaştır.", "code": "p=rng.beta(2,6,2000);y=rng.binomial(1,p);fp_cost,fn_cost=2,10;thresholds=np.linspace(0,1,101);cost=[]\nfor t in thresholds:\n pred=p>=t;cost.append((fp_cost*np.sum(pred&(y==0))+fn_cost*np.sum((~pred)&(y==1)))/len(y))\nprint({'teorik_esik':fp_cost/(fp_cost+fn_cost),'orneklem_min':thresholds[np.argmin(cost)],'min_ortalama_maliyet':min(cost)})\nplt.plot(thresholds,cost);plt.axvline(fp_cost/(fp_cost+fn_cost),c='tab:orange');plt.xlabel('Eşik');plt.ylabel('Kayıt başına maliyet')", "id": "s91", "module": 22, "title": "Bayes karar kuralı ve hata maliyeti", "output": "{'teorik_esik': 0.16666666666666666, 'orneklem_min': np.float64(0.19), 'min_ortalama_maliyet': np.float64(1.328)}\n", "image": "advanced/s91.png", "notebook": "advanced/konu_23.ipynb", "script": "advanced/konu_23.py"}, "s92": {"question": "Daha çok veri mi daha iyi model mi gerekir?", "reading": "Eğitim büyüklüğüne göre tekrarlı doğrulama hatasını oku.", "limit": "Bağımsız test aynı kalır; simülasyon eğrisi başka evrene otomatik taşınmaz.", "task": "Polinom derecesini 3’ten 1’e düşür; doygunlaşan hatayı yorumla.", "code": "xt=rng.uniform(-1,1,500);yt=np.sin(3*xt)+rng.normal(0,.3,500);sizes=[20,40,80,160,320];errors=[]\nfor n in sizes:\n vals=[]\n for rep in range(15):\n  x=rng.uniform(-1,1,n);y=np.sin(3*x)+rng.normal(0,.3,n);m=make_pipeline(PolynomialFeatures(3),Ridge(alpha=.01));m.fit(x[:,None],y);vals.append(mean_squared_error(yt,m.predict(xt[:,None])))\n errors.append([np.mean(vals),np.std(vals)])\nerrors=np.array(errors);print(pd.DataFrame({'n':sizes,'ortalama_test_MSE':errors[:,0],'tekrar_SD':errors[:,1]}));plt.errorbar(sizes,errors[:,0],yerr=errors[:,1],fmt='o-');plt.axhline(.3**2,c='tab:orange');plt.xlabel('Eğitim n');plt.ylabel('Test MSE ± tekrar SD')", "id": "s92", "module": 22, "title": "Öğrenme eğrileri ve veri değeri", "output": "     n  ortalama_test_MSE  tekrar_SD\n0   20           0.125963   0.032189\n1   40           0.099773   0.006407\n2   80           0.096143   0.004347\n3  160           0.091031   0.001254\n4  320           0.090963   0.001034\n", "image": "advanced/s92.png", "notebook": "advanced/konu_23.ipynb", "script": "advanced/konu_23.py"}, "s93": {"question": "Aynı doğrulukta daha emin yanlış karar neden daha pahalı?", "reading": "İki olasılık tahmininin log kaybını ve Brier’ını karşılaştır.", "limit": "Kayıplar olasılık kalitesini ölçer; sıralama kalitesi veya eşik maliyetiyle aynı değildir.", "task": "Yanlış kayda verilen .99 olasılığını .7 yap; doğruluk değişmeden kaybı izle.", "code": "y=np.array([1,0,1,0]);p1=np.array([.7,.2,.6,.6]);p2=np.array([.99,.01,.99,.99]);print(pd.DataFrame([{'model':name,'log_kayip':log_loss(y,p),'Brier':brier_score_loss(y,p),'dogruluk':np.mean((p>=.5)==y)} for name,p in [('Ilımlı',p1),('Aşırı emin',p2)]]))\nplt.plot(range(1,5),-(y*np.log(p1)+(1-y)*np.log1p(-p1)),'o-',label='Ilımlı');plt.plot(range(1,5),-(y*np.log(p2)+(1-y)*np.log1p(-p2)),'o-',label='Aşırı emin');plt.xlabel('Kayıt');plt.ylabel('Negatif log olabilirlik');plt.legend()", "id": "s93", "module": 23, "title": "Olabilirlik, çapraz entropi ve log kaybı", "output": "        model  log_kayip   Brier  dogruluk\n0      Ilımlı   0.501734  0.1625      0.75\n1  Aşırı emin   1.158830  0.2451      0.75\n", "image": "advanced/s93.png", "notebook": "advanced/konu_24.ipynb", "script": "advanced/konu_24.py"}, "s94": {"question": "Adım boyu optimizasyonu nasıl bozabilir?", "reading": "Kayıp izlerini küçük, uygun ve büyük adım için karşılaştır.", "limit": "Konveks tek parametreli kare kayıp örneği; derin ağların tüm davranışını temsil etmez.", "task": "Öğrenme hızına 1.1 ekle; taşma yerine ilk 20 adımda yükselen kaybı gözle.", "code": "x=rng.normal(size=100);y=2*x+rng.normal(0,.3,100)\nfor rate in [.01,.1,.8]:\n b=0.;history=[]\n for step in range(60):\n  pred=b*x;history.append(np.mean((pred-y)**2));grad=2*np.mean(x*(pred-y));b-=rate*grad\n print({'adim':rate,'son_beta':b,'son_kayip':history[-1]});plt.semilogy(history,label=f'η={rate}')\nplt.xlabel('Gradyan adımı');plt.ylabel('MSE · log ölçek');plt.legend()", "id": "s94", "module": 23, "title": "Gradyan inişi ve stokastik optimizasyon", "output": "{'adim': 0.01, 'son_beta': np.float64(1.2949633208807263), 'son_kayip': np.float64(0.5762447424963499)}\n{'adim': 0.1, 'son_beta': np.float64(2.0562781922604976), 'son_kayip': np.float64(0.08421888194582039)}\n{'adim': 0.8, 'son_beta': np.float64(2.0563216685858157), 'son_kayip': np.float64(0.08421887972373926)}\n", "image": "advanced/s94.png", "notebook": "advanced/konu_24.ipynb", "script": "advanced/konu_24.py"}, "s95": {"question": "Gradyanı sayısal farkla doğrulayabilir miyim?", "reading": "Analitik ve sonlu fark gradyanlarının eşleşmesini denetle.", "limit": "Kovaryans özdeğerleri ölçekteki değişime duyarlıdır; merkezleme ve n−1 tanımı korunur.", "task": "İkinci sütunu 100 ile çarp; kovaryans ve gradyan ölçeğinin etkisini yaz.", "code": "X=rng.normal(size=(80,2));X[:,1]=.7*X[:,0]+.5*X[:,1];y=X@np.array([2.,-1.])+rng.normal(0,.3,80);b=np.array([.5,.5]);loss=lambda v:np.mean((X@v-y)**2);g=2*X.T@(X@b-y)/len(y);eps=1e-6;numeric=np.array([(loss(b+eps*np.eye(2)[j])-loss(b-eps*np.eye(2)[j]))/(2*eps) for j in range(2)])\nprint({'gradyan':g.tolist(),'sonlu_fark':numeric.tolist(),'kovaryans':np.cov(X,rowvar=False).tolist()});assert np.allclose(g,numeric,atol=1e-7)\nplt.scatter(*X.T,s=15);plt.axis('equal');plt.xlabel('x1');plt.ylabel('x2')", "id": "s95", "module": 23, "title": "Vektörler, kovaryans matrisi ve gradyan", "output": "{'gradyan': [-0.9049179600196501, 0.13106047921004177], 'sonlu_fark': [-0.9049179600095769, 0.13106047919153596], 'kovaryans': [[0.7933380973651366, 0.4788164998753933], [0.4788164998753933, 0.5323672287029223]]}\n", "image": "advanced/s95.png", "notebook": "advanced/konu_24.ipynb", "script": "advanced/konu_24.py"}, "s96": {"question": "Nokta tahminine hangi aralığı ekleyebilirim?", "reading": "Kalibrasyon ve testteki kapsama ile aralık genişliğini birlikte oku.", "limit": "Split konformal marjinal kapsama verir; değiştirilebilirlik ve eğitimden ayrı kalibrasyon gerekir.", "task": "α=.1 yerine .05 yap; sonlu sıra düzeltmesini ve genişliği raporla.", "code": "x=rng.uniform(-2,2,(450,1));y=2*x[:,0]+rng.normal(size=450);model=LinearRegression().fit(x[:200],y[:200]);cal=np.abs(y[200:325]-model.predict(x[200:325]));alpha=.1;rank=int(np.ceil((len(cal)+1)*(1-alpha)));q=np.sort(cal)[rank-1];pred=model.predict(x[325:]);covered=np.abs(y[325:]-pred)<=q\nprint({'kalibrasyon_n':len(cal),'sira':rank,'q':q,'test_kapsama':covered.mean(),'genislik':2*q});order=np.argsort(x[325:,0]);xx=x[325:,0][order];pp=pred[order];plt.scatter(xx,y[325:][order],s=12);plt.plot(xx,pp,c='tab:orange');plt.fill_between(xx,pp-q,pp+q,alpha=.2);plt.xlabel('x');plt.ylabel('Yeni y ve tahmin aralığı')", "id": "s96", "module": 23, "title": "Tahmin belirsizliği ve konformal aralık", "output": "{'kalibrasyon_n': 125, 'sira': 114, 'q': np.float64(1.6264343333950386), 'test_kapsama': np.float64(0.92), 'genislik': np.float64(3.2528686667900772)}\n", "image": "advanced/s96.png", "notebook": "advanced/konu_24.ipynb", "script": "advanced/konu_24.py"}, "s97": {"question": "Sınıfların kovaryansı farklıysa doğrusal sınır yeterli mi?", "reading": "LDA ve QDA’nın aynı testteki olasılık kaybını karşılaştır.", "limit": "QDA daha çok parametre tahmin eder; az veriyle yüksek varyans yaratabilir.", "task": "Her sınıfın n değerini 200’den 30’a indir; test sonuçlarının kararlılığını tartış.", "code": "from sklearn.discriminant_analysis import LinearDiscriminantAnalysis, QuadraticDiscriminantAnalysis\nX=np.r_[rng.multivariate_normal([-1,0],[[1,.7],[.7,1]],200),rng.multivariate_normal([1,0],[[1,-.6],[-.6,.5]],200)];y=np.repeat([0,1],200);a,b,c,d=train_test_split(X,y,test_size=.35,stratify=y,random_state=7)\nfor model in [LinearDiscriminantAnalysis(),QuadraticDiscriminantAnalysis()]:\n model.fit(a,c);p=model.predict_proba(b)[:,1];print(type(model).__name__,{'logloss':log_loss(d,p),'AUC':roc_auc_score(d,p)})\nplt.scatter(*b.T,c=d,s=18,cmap='coolwarm');plt.xlabel('x1 · test');plt.ylabel('x2 · test')", "id": "s97", "module": 24, "title": "LDA, QDA ve üretici sınıflandırma", "output": "LinearDiscriminantAnalysis {'logloss': 0.3604636813317358, 'AUC': 0.9216326530612245}\nQuadraticDiscriminantAnalysis {'logloss': 0.2344054107758948, 'AUC': 0.9648979591836735}\n", "image": "advanced/s97.png", "notebook": "advanced/konu_25.ipynb", "script": "advanced/konu_25.py"}, "s98": {"question": "Bağımsızlık varsayımı olasılık güvenini nasıl etkiler?", "reading": "Aynı sinyalin kopyalarını ekleyerek NB ile lojistiği karşılaştır.", "limit": "Naive Bayes’in koşullu bağımsızlığı sınıf koşulundadır; iyi doğruluk iyi kalibrasyon garantisi değildir.", "task": "Gürültülü kopya sayısını 1’den 5’e çıkar; log kaybını izle.", "code": "from sklearn.naive_bayes import GaussianNB\nX,y=make_classification(n_samples=600,n_features=4,n_informative=2,n_redundant=0,random_state=7);X=np.c_[X,X[:,0]+rng.normal(0,.05,len(X))];a,b,c,d=train_test_split(X,y,test_size=.35,stratify=y,random_state=7);names=[];loss=[]\nfor name,model in [('Gaussian NB',GaussianNB()),('Lojistik',make_pipeline(StandardScaler(),LogisticRegression()))]:\n model.fit(a,c);p=model.predict_proba(b)[:,1];names.append(name);loss.append(log_loss(d,p));print(name,{'logloss':loss[-1],'Brier':brier_score_loss(d,p)})\nplt.bar(names,loss);plt.ylabel('Bağımsız test log kaybı')", "id": "s98", "module": 24, "title": "Naive Bayes ve koşullu bağımsızlık", "output": "Gaussian NB {'logloss': 0.37269096080727876, 'Brier': 0.12260758182959022}\nLojistik {'logloss': 0.32423478279079876, 'Brier': 0.10162618279597797}\n", "image": "advanced/s98.png", "notebook": "advanced/konu_25.ipynb", "script": "advanced/konu_25.py"}, "s99": {"question": "İlgisiz boyutlar yakın komşuyu neden bozar?", "reading": "Eklenen gürültü boyutlarıyla test doğruluğunu karşılaştır.", "limit": "Ölçekleme eğitim içinde öğrenilir; tek bölme boyut etkisinin kesin büyüklüğü değildir.", "task": "Komşu sayısını 7’den 25’e çıkar; boyut etkisini yeniden değerlendir.", "code": "from sklearn.neighbors import KNeighborsClassifier\nX,y=make_moons(n_samples=600,noise=.2,random_state=7);dims=[0,5,20,60];scores=[]\nfor extra in dims:\n xx=np.c_[X,rng.normal(size=(len(X),extra))];a,b,c,d=train_test_split(xx,y,test_size=.35,stratify=y,random_state=7);m=make_pipeline(StandardScaler(),KNeighborsClassifier(7));m.fit(a,c);scores.append(m.score(b,d))\nprint(pd.DataFrame({'ek_gurultu_boyutu':dims,'test_dogruluk':scores}));plt.plot(dims,scores,'o-');plt.xlabel('Ek gürültü boyutu');plt.ylabel('Test doğruluğu')", "id": "s99", "module": 24, "title": "k-en yakın komşu ve boyut etkisi", "output": "   ek_gurultu_boyutu  test_dogruluk\n0                  0       0.980952\n1                  5       0.880952\n2                 20       0.833333\n3                 60       0.719048\n", "image": "advanced/s99.png", "notebook": "advanced/konu_25.ipynb", "script": "advanced/konu_25.py"}, "s100": {"question": "Doğrusal sınır yerine çekirdek ne kazandırır?", "reading": "Aynı test noktalarında doğrusal ve RBF kararını karşılaştır.", "limit": "C/gamma testten seçilmez; burada sabit eğitim ayarlarıdır. SVM decision_function kalibre olasılık değildir.", "task": "gamma=1 yerine 20 kullan; eğitim/test farkını incele.", "code": "from sklearn.svm import SVC\nX,y=make_moons(n_samples=400,noise=.22,random_state=7);a,b,c,d=train_test_split(X,y,test_size=.35,stratify=y,random_state=7)\nfor kernel in ['linear','rbf']:\n m=make_pipeline(StandardScaler(),SVC(C=1,kernel=kernel,gamma=1));m.fit(a,c);print(kernel,{'egitim':m.score(a,c),'test':m.score(b,d)})\nplt.scatter(*b.T,c=d,s=20,cmap='coolwarm');plt.xlabel('Test x1');plt.ylabel('Test x2')", "id": "s100", "module": 24, "title": "Marj, SVM ve çekirdekler", "output": "linear {'egitim': 0.8730769230769231, 'test': 0.8642857142857143}\nrbf {'egitim': 0.9653846153846154, 'test': 0.9642857142857143}\n", "image": "advanced/s100.png", "notebook": "advanced/konu_25.ipynb", "script": "advanced/konu_25.py"}, "s101": {"question": "Daha derin ağaç neden daha iyi test sonucu vermeyebilir?", "reading": "Derinliğe göre eğitim/test kaybını karşılaştır.", "limit": "Ağaç parametreleri testten seçilmez; tek bölme genelleme belirsizliğini özetlemez.", "task": "min_samples_leaf değerini 1’den 10’a çıkar; aşırı uyumu incele.", "code": "from sklearn.tree import DecisionTreeClassifier\nX,y=make_classification(n_samples=600,n_features=6,n_informative=3,flip_y=.1,random_state=7);a,b,c,d=train_test_split(X,y,test_size=.35,stratify=y,random_state=7);rows=[]\nfor depth in [1,2,3,5,9,None]:\n m=DecisionTreeClassifier(max_depth=depth,random_state=7);m.fit(a,c);rows.append([str(depth),1-m.score(a,c),1-m.score(b,d)])\nt=pd.DataFrame(rows,columns=['derinlik','egitim_hata','test_hata']);print(t);plt.plot(t.derinlik,t.egitim_hata,'o-',label='Eğitim');plt.plot(t.derinlik,t.test_hata,'o-',label='Test');plt.xlabel('Maksimum derinlik');plt.ylabel('Hata payı');plt.legend()", "id": "s101", "module": 25, "title": "Karar ağaçları ve safsızlık", "output": "  derinlik  egitim_hata  test_hata\n0        1     0.120513   0.161905\n1        2     0.076923   0.142857\n2        3     0.061538   0.138095\n3        5     0.030769   0.133333\n4        9     0.000000   0.157143\n5     None     0.000000   0.157143\n", "image": "advanced/s101.png", "notebook": "advanced/konu_26.ipynb", "script": "advanced/konu_26.py"}, "s102": {"question": "Toplulukta ağaç sayısı kadar korelasyon neden önemli?", "reading": "max_features değişince tek ağaç tahminlerinin korelasyonunu ve orman başarısını birlikte oku.", "limit": "Korelasyon aynı test noktalarında tanımlıdır; hata korelasyonu ve tahmin korelasyonu farklıdır.", "task": "Ağaç sayısını 80’den 10’a indir; korelasyonun tek açıklayıcı olmadığını göster.", "code": "from sklearn.ensemble import RandomForestClassifier\nX,y=make_classification(n_samples=700,n_features=12,n_informative=4,random_state=7);a,b,c,d=train_test_split(X,y,test_size=.35,stratify=y,random_state=7);rows=[]\nfor features in ['sqrt',1.0]:\n m=RandomForestClassifier(n_estimators=80,max_features=features,min_samples_leaf=3,random_state=7,n_jobs=1);m.fit(a,c);p=np.array([tree.predict_proba(b)[:,1] for tree in m.estimators_]);corr=np.corrcoef(p);off=corr[np.triu_indices_from(corr,1)];rows.append([str(features),np.nanmean(off),m.score(b,d)])\nprint(pd.DataFrame(rows,columns=['max_features','tahmin_korelasyonu','test_dogruluk']));plt.bar([r[0] for r in rows],[r[2] for r in rows]);plt.ylim(.5,1);plt.ylabel('Test doğruluğu')", "id": "s102", "module": 25, "title": "Bagging, rastgele orman ve korelasyon", "output": "  max_features  tahmin_korelasyonu  test_dogruluk\n0         sqrt            0.622355       0.910204\n1          1.0            0.706773       0.902041\n", "image": "advanced/s102.png", "notebook": "advanced/konu_26.ipynb", "script": "advanced/konu_26.py"}, "s103": {"question": "Boosting adımları ne zaman aşırı uyuma döner?", "reading": "Sabit ayarda adım sayısı boyunca eğitim ve test log kaybını izle.", "limit": "Test eğrisi öğretim gözlemidir; üretimde erken durdurma ayrı doğrulama verisinden seçilir.", "task": "Öğrenme hızını .1’den .03’e düşür; aynı adım sayısının anlamını tartış.", "code": "from sklearn.ensemble import GradientBoostingClassifier\nX,y=make_classification(n_samples=600,n_features=8,n_informative=4,flip_y=.1,random_state=7);a,b,c,d=train_test_split(X,y,test_size=.35,stratify=y,random_state=7);m=GradientBoostingClassifier(n_estimators=150,learning_rate=.1,max_depth=2,random_state=7);m.fit(a,c);train=[log_loss(c,p) for p in m.staged_predict_proba(a)];test=[log_loss(d,p) for p in m.staged_predict_proba(b)];print({'son_egitim':train[-1],'son_test':test[-1]});plt.plot(train,label='Eğitim');plt.plot(test,label='Test');plt.xlabel('Eklenen ağaç');plt.ylabel('Log kaybı');plt.legend()", "id": "s103", "module": 25, "title": "Boosting ve eklemeli öğrenme", "output": "{'son_egitim': 0.12188235705062388, 'son_test': 0.4224757007496858}\n", "image": "advanced/s103.png", "notebook": "advanced/konu_26.ipynb", "script": "advanced/konu_26.py"}, "s104": {"question": "Ağ kapasitesi ve ceza birlikte nasıl değerlendirilir?", "reading": "Aynı testte farklı ağların kaybını eğitim kaybıyla karşılaştır.", "limit": "Küçük MLP öğretim modelidir; derin öğrenmenin bütün mimarilerini temsil etmez. Yakınsama uyarısı model tanısıdır.", "task": "alpha=.01 yerine 1 kullan; model karmaşıklığı ve kaybı karşılaştır.", "code": "from sklearn.neural_network import MLPClassifier\nX,y=make_moons(n_samples=500,noise=.25,random_state=7);a,b,c,d=train_test_split(X,y,test_size=.35,stratify=y,random_state=7);rows=[]\nfor width in [4,16,48]:\n m=make_pipeline(StandardScaler(),MLPClassifier(hidden_layer_sizes=(width,),alpha=.01,max_iter=1200,early_stopping=True,n_iter_no_change=30,random_state=7));m.fit(a,c);rows.append([width,log_loss(c,m.predict_proba(a)),log_loss(d,m.predict_proba(b))])\nt=pd.DataFrame(rows,columns=['gizli_birim','egitim_logloss','test_logloss']);print(t);plt.plot(t.gizli_birim,t.egitim_logloss,'o-',label='Eğitim');plt.plot(t.gizli_birim,t.test_logloss,'o-',label='Test');plt.xlabel('Gizli birim');plt.ylabel('Log kaybı');plt.legend()", "id": "s104", "module": 25, "title": "Sinir ağlarının istatistiksel temeli", "output": "   gizli_birim  egitim_logloss  test_logloss\n0            4        0.493039      0.461874\n1           16        0.536314      0.517628\n2           48        0.531449      0.499694\n", "image": "advanced/s104.png", "notebook": "advanced/konu_26.ipynb", "script": "advanced/konu_26.py"}, "s105": {"question": "Seçtiğim en iyi doğrulama skoru neden iyimser olabilir?", "reading": "İç seçim skoruyla dış kat sonuçlarını ayır.", "limit": "Ölçekleme pipeline içindedir. İç içe CV belirlenen arama prosedürünü değerlendirir, her veri sorununu çözmez.", "task": "C adaylarına 10 ve 100 ekle; seçim skorunu dış sonuçla karşılaştır.", "code": "from sklearn.svm import SVC\nX,y=make_classification(n_samples=240,n_features=8,n_informative=4,random_state=7);outer=StratifiedKFold(4,shuffle=True,random_state=7);rows=[]\nfor fold,(tr,te) in enumerate(outer.split(X,y),1):\n search=GridSearchCV(make_pipeline(StandardScaler(),SVC(kernel='rbf')),{'svc__C':[.1,1,10],'svc__gamma':[.01,.1,1]},cv=3,scoring='accuracy');search.fit(X[tr],y[tr]);rows.append([fold,search.best_score_,search.score(X[te],y[te])])\nt=pd.DataFrame(rows,columns=['dis_kat','ic_secim_skoru','dis_test_skoru']);print(t);print('Dış ortalama:',t.dis_test_skoru.mean());plt.plot(t.dis_kat,t.ic_secim_skoru,'o-',label='İç seçim');plt.plot(t.dis_kat,t.dis_test_skoru,'o-',label='Dış test');plt.xlabel('Dış kat');plt.ylabel('Doğruluk');plt.legend()", "id": "s105", "module": 26, "title": "İç içe çapraz doğrulama ve seçim yanlılığı", "output": "   dis_kat  ic_secim_skoru  dis_test_skoru\n0        1        0.900000        0.850000\n1        2        0.872222        0.866667\n2        3        0.894444        0.916667\n3        4        0.916667        0.833333\nDış ortalama: 0.8666666666666667\n", "image": "advanced/s105.png", "notebook": "advanced/konu_27.ipynb", "script": "advanced/konu_27.py"}, "s106": {"question": "Nadir olayda ROC iyi görünürken alarm yükü nasıl olabilir?", "reading": "ROC-AUC yanında PR ve taban oranını raporla.", "limit": "Average precision bir eşikte precision değildir; değerlendirme bağımsız testte yapılır.", "task": "Pozitif payını .1’den .02’ye indir; ROC ve AP değişimini incele.", "code": "from sklearn.metrics import RocCurveDisplay, PrecisionRecallDisplay\nX,y=make_classification(n_samples=1500,n_features=6,n_informative=3,weights=[.9,.1],random_state=7);a,b,c,d=train_test_split(X,y,test_size=.4,stratify=y,random_state=7);m=make_pipeline(StandardScaler(),LogisticRegression());m.fit(a,c);p=m.predict_proba(b)[:,1];print({'taban':d.mean(),'ROC_AUC':roc_auc_score(d,p),'AP':average_precision_score(d,p)})\nPrecisionRecallDisplay.from_predictions(d,p,ax=plt.gca());plt.axhline(d.mean(),c='tab:orange',label='Taban oranı');plt.legend()", "id": "s106", "module": 26, "title": "ROC, precision–recall ve dengesizlik", "output": "{'taban': np.float64(0.105), 'ROC_AUC': 0.9417693831101651, 'AP': 0.8204804018729897}\n", "image": "advanced/s106.png", "notebook": "advanced/konu_27.ipynb", "script": "advanced/konu_27.py"}, "s107": {"question": "Kalibratörü test verisinden öğrenmeden nasıl sınarım?", "reading": "Kalibrasyon eğrilerini ve Brier’ı aynı bağımsız testte kıyasla.", "limit": "CalibratedClassifierCV eğitim içinde CV kullanır; final test ayarlamada kullanılmaz.", "task": "Kalibrasyon yöntemini sigmoid yerine isotonic yap; veri ihtiyacını tartış.", "code": "from sklearn.calibration import CalibratedClassifierCV, calibration_curve\nfrom sklearn.ensemble import RandomForestClassifier\nX,y=make_classification(n_samples=1200,n_features=8,n_informative=4,random_state=7);a,b,c,d=train_test_split(X,y,test_size=.35,stratify=y,random_state=7);base=RandomForestClassifier(n_estimators=60,min_samples_leaf=8,random_state=7,n_jobs=1);cal=CalibratedClassifierCV(base,method='sigmoid',cv=3);base.fit(a,c);cal.fit(a,c)\nfor name,m in [('Ham',base),('Sigmoid',cal)]:\n p=m.predict_proba(b)[:,1];print(name,'Brier',brier_score_loss(d,p));obs,mean=calibration_curve(d,p,n_bins=6);plt.plot(mean,obs,'o-',label=name)\nplt.plot([0,1],[0,1],'--',c='gray');plt.xlabel('Ortalama tahmin');plt.ylabel('Gözlenen pay');plt.legend()", "id": "s107", "module": 26, "title": "Kalibrasyon, Brier ve güvenilirlik diyagramı", "output": "Ham Brier 0.08859886760562631\nSigmoid Brier 0.08976294581848476\n", "image": "advanced/s107.png", "notebook": "advanced/konu_27.ipynb", "script": "advanced/konu_27.py"}, "s108": {"question": "İki model aynı kayıtlarda nasıl karşılaştırılır?", "reading": "Satırları çift olarak yeniden çekerek kayıp farkı aralığını kur.", "limit": "Bağımsız test kayıtları varsayılır; zaman veya müşteri kümelerinde blok/küme bootstrap gerekir.", "task": "İki modelin aynı satırlardaki korelasyonunu artır; bağımsız çekimin neden yanlış olduğunu açıkla.", "code": "y=rng.normal(size=250);pA=y+rng.normal(0,1,250);pB=y+rng.normal(0,.9,250);diff=(pA-y)**2-(pB-y)**2;draws=rng.choice(diff,(2000,len(diff))).mean(axis=1);print({'MSE_A_eksi_B':diff.mean(),'esli_bootstrap_CI95':np.quantile(draws,[.025,.975]).tolist()})\nplt.hist(draws,bins=35);plt.axvline(0,c='tab:orange');plt.xlabel('Ortalama eşleştirilmiş kayıp farkı');plt.ylabel('Tekrar')", "id": "s108", "module": 26, "title": "Model karşılaştırması ve eşleştirilmiş belirsizlik", "output": "{'MSE_A_eksi_B': np.float64(0.3019808286429534), 'esli_bootstrap_CI95': [0.06955466381269268, 0.5414162544434127]}\n", "image": "advanced/s108.png", "notebook": "advanced/konu_27.ipynb", "script": "advanced/konu_27.py"}, "s109": {"question": "Korelasyonlu iki ölçümde uzaklığı nasıl değerlendiririm?", "reading": "Aynı Öklid uzaklığında noktaların Mahalanobis farkını gör.", "limit": "Kovaryans tahmini bağımsız referanstan gelir; yüksek boyut/az örneklemde regularizasyon gerekir.", "task": "Korelasyonu .85’ten 0’a indir; eliptik uzaklığın değişimini incele.", "code": "X=rng.multivariate_normal([0,0],[[1,.85],[.85,1]],400);cov=np.cov(X,rowvar=False);center=X.mean(axis=0);points=np.array([[2,2],[2,-2]]);delta=points-center;dist2=np.einsum('ij,jk,ik->i',delta,np.linalg.inv(cov),delta);print({'noktalar':points.tolist(),'Mahalanobis_kare':dist2.tolist(),'chi2_95':stats.chi2.ppf(.95,2)})\nplt.scatter(*X.T,s=10,alpha=.3);plt.scatter(*points.T,s=80,c=['tab:green','tab:red']);plt.axis('equal');plt.xlabel('x1');plt.ylabel('x2')", "id": "s109", "module": 27, "title": "Çok değişkenli normal ve Mahalanobis uzaklığı", "output": "{'noktalar': [[2, 2], [2, -2]], 'Mahalanobis_kare': [5.036603068444901, 54.20687505846167], 'chi2_95': np.float64(5.991464547107979)}\n", "image": "advanced/s109.png", "notebook": "advanced/konu_28.ipynb", "script": "advanced/konu_28.py"}, "s110": {"question": "EM ile yumuşak küme üyeliğini nasıl öğrenirim?", "reading": "Sert etiket yerine üyelik olasılığı ve BIC’yi birlikte incele.", "limit": "Karışım etiketleri yer değiştirebilir; yerel optimum ve normal bileşen varsayımı kontrol edilir.", "task": "Bileşen ortalamalarını yaklaştır; üyelik belirsizliğini gör.", "code": "from sklearn.mixture import GaussianMixture\nX=np.r_[rng.normal(-1.5,.7,(180,1)),rng.normal(1.5,1,(220,1))];rows=[];models=[]\nfor k in [1,2,3,4]:\n m=GaussianMixture(k,n_init=5,random_state=7).fit(X);models.append(m);rows.append([k,m.bic(X),m.converged_])\nprint(pd.DataFrame(rows,columns=['bilesen','BIC','yakinsadi']));m=models[1];print('Ortalama:',m.means_.ravel(),'Ağırlık:',m.weights_);grid=np.linspace(-5,5,300)[:,None];plt.hist(X.ravel(),bins=35,density=True,alpha=.4);plt.plot(grid[:,0],np.exp(m.score_samples(grid)));plt.xlabel('Ölçüm');plt.ylabel('Yoğunluk')", "id": "s110", "module": 27, "title": "Gaussian karışımlar ve EM", "output": "   bilesen          BIC  yakinsadi\n0        1  1587.072667       True\n1        2  1491.515717       True\n2        3  1509.129477       True\n3        4  1523.128281       True\nOrtalama: [-1.4289  1.6145] Ağırlık: [0.4646 0.5354]\n", "image": "advanced/s110.png", "notebook": "advanced/konu_28.ipynb", "script": "advanced/konu_28.py"}, "s111": {"question": "Ortak faktör ile toplam varyans aynı hedef mi?", "reading": "Faktör yükleri ve özgül hata varyanslarını ayır.", "limit": "Faktörün işareti/rotasyonu tanımlanabilirlik sınırı taşır; faktörler kendiliğinden gerçek neden değildir.", "task": "Son ölçümün hata sapmasını artır; özgül varyansı incele.", "code": "from sklearn.decomposition import FactorAnalysis\nlatent=rng.normal(size=(400,1));load=np.array([[1,.8,.6,1.2]]);X=latent@load+rng.normal(size=(400,4))*np.array([.3,.5,1.,.4]);m=FactorAnalysis(1,random_state=7).fit(X);print({'yukler':m.components_.tolist(),'ozgul_varyans':m.noise_variance_.tolist()});plt.bar(np.arange(4)-.18,m.components_[0],.36,label='Yük');plt.bar(np.arange(4)+.18,m.noise_variance_,.36,label='Özgül varyans');plt.xlabel('Ölçüm');plt.legend()", "id": "s111", "module": 27, "title": "Faktör analizi ve gizli değişkenler", "output": "{'yukler': [[-0.9682870992856426, -0.7540028695641754, -0.5376334983836656, -1.1359040492971137]], 'ozgul_varyans': [0.08752570486027322, 0.2592326809545812, 0.9984328635419379, 0.16849395623375774]}\n", "image": "advanced/s111.png", "notebook": "advanced/konu_28.ipynb", "script": "advanced/konu_28.py"}, "s112": {"question": "İki boyutlu adalar doğal sınıf kanıtı mı?", "reading": "Aynı noktaların farklı perplexity değerlerinde yerleşimini karşılaştır.", "limit": "t-SNE eksenleri ve küme arası uzaklık global geometri değildir; UMAP burada eğitilmez, ayrı algoritmadır.", "task": "Perplexity=10 yerine 50 kullan; etiketlerin değişmediğini, yerleşimin değiştiğini göster.", "code": "from sklearn.manifold import TSNE\nX,y=make_classification(n_samples=180,n_features=6,n_informative=3,n_classes=3,n_clusters_per_class=1,random_state=7);X=StandardScaler().fit_transform(X);m=TSNE(perplexity=20,max_iter=500,init='pca',random_state=7);z=m.fit_transform(X);print({'KL_objektif':m.kl_divergence_,'n':len(X),'perplexity':20});plt.scatter(*z.T,c=y,s=20,cmap='viridis');plt.xlabel('t-SNE 1 · keyfi eksen');plt.ylabel('t-SNE 2 · keyfi eksen')", "id": "s112", "module": 27, "title": "Manifold, t-SNE/UMAP ve görsel yanılsamalar", "output": "{'KL_objektif': 0.5509330630302429, 'n': 180, 'perplexity': 20}\n", "image": "advanced/s112.png", "notebook": "advanced/konu_28.ipynb", "script": "advanced/konu_28.py"}, "s113": {"question": "Tedavi seçimiyle müdahale etkisini nasıl ayırırım?", "reading": "Ham farkı IPW ve bilinen simülasyon etkisiyle karşılaştır.", "limit": "IPW gözlenen karıştırıcılar, doğru eğilim modeli, tutarlılık ve pozitiflik ister; gizli karıştırıcıyı çözmez.", "task": "Seçilim katsayısını 1’den 2’ye çıkar; uç ağırlık ve ESS’yi incele.", "code": "x=rng.normal(size=1000);prop=special.expit(x);t=rng.binomial(1,prop);y=2*t+3*x+rng.normal(size=1000);m=LogisticRegression(C=1e5).fit(x[:,None],t);e=m.predict_proba(x[:,None])[:,1]\nif np.min(e)<.01 or np.max(e)>.99:print('UYARI: zayıf destek / uç ağırlık')\nw1=t/e;w0=(1-t)/(1-e);effect=np.sum(w1*y)/w1.sum()-np.sum(w0*y)/w0.sum();ess=lambda w:w.sum()**2/(w@w)\nprint({'ham_fark':y[t==1].mean()-y[t==0].mean(),'Hajek_IPW':effect,'gercek_etki':2,'tedavi_ESS':ess(w1),'kontrol_ESS':ess(w0)})\nplt.hist(e[t==0],bins=20,alpha=.5,label='Kontrol');plt.hist(e[t==1],bins=20,alpha=.5,label='Tedavi');plt.xlabel('Tahmin edilen eğilim');plt.ylabel('Kayıt');plt.legend()", "id": "s113", "module": 28, "title": "Eğilim skoru, eşleştirme ve IPW", "output": "{'ham_fark': np.float64(4.148999357550378), 'Hajek_IPW': np.float64(1.887815662792634), 'gercek_etki': 2, 'tedavi_ESS': np.float64(459.1316205973227), 'kontrol_ESS': np.float64(355.232109176364)}\n", "image": "advanced/s113.png", "notebook": "advanced/konu_29.ipynb", "script": "advanced/konu_29.py"}, "s114": {"question": "Dışsal araç endojenlik sorununu nasıl değiştirebilir?", "reading": "OLS, 2SLS ve bilinen üretim etkisini karşılaştır.", "limit": "Araç dışsallığı ve dışlama veriyle tek başına kanıtlanmaz; ikinci aşama saf OLS standart hatası geçerli değildir.", "task": "Araç katsayısını 1’den .1’e indir; ilk aşama F ve tahmini incele.", "code": "n=1200;z=rng.normal(size=n);u=rng.normal(size=n);t=z+.8*u+rng.normal(size=n);y=2*t+u+rng.normal(size=n);first=sm.OLS(t,sm.add_constant(z)).fit();that=first.fittedvalues;beta_iv=sm.OLS(y,sm.add_constant(that)).fit().params[1];ols=sm.OLS(y,sm.add_constant(t)).fit().params[1]\nprint({'OLS':ols,'2SLS_nokta':beta_iv,'gercek':2,'ilk_asama_F':float(first.fvalue),'CI':'Bu örnekte IV güven aralığı hesaplanmadı'})\nplt.bar(['OLS','2SLS','Gerçek'],[ols,beta_iv,2]);plt.ylabel('Etki tahmini')", "id": "s114", "module": 28, "title": "Araç değişken ve doğal deney", "output": "{'OLS': np.float64(2.310819632947627), '2SLS_nokta': np.float64(2.0463583425656537), 'gercek': 2, 'ilk_asama_F': 744.3460653854601, 'CI': 'Bu örnekte IV güven aralığı hesaplanmadı'}\n", "image": "advanced/s114.png", "notebook": "advanced/konu_29.ipynb", "script": "advanced/konu_29.py"}, "s115": {"question": "Bir eşik çevresinde yerel etkiyi nasıl kurarım?", "reading": "İki taraftaki yerel doğruların eşikteki sıçramasını oku.", "limit": "Süreklilik, manipülasyon olmaması ve uygun bant gerekir; etki eşik çevresine aittir.", "task": "Bant genişliğini .6’dan .3’e indir; n ve aralığın değişimini karşılaştır.", "code": "x=rng.uniform(-2,2,800);t=(x>=0).astype(int);y=5+2*x+1.5*t+.4*x*t+rng.normal(size=len(x));band=.6;keep=np.abs(x)<=band;df=pd.DataFrame({'x':x[keep],'t':t[keep],'y':y[keep]});fit=smf.ols('y ~ x * t',df).fit(cov_type='HC1');print({'yerel_n':int(keep.sum()),'sicrama':fit.params['t'],'HC1_CI':fit.conf_int().loc['t'].tolist(),'gercek':1.5})\nplt.scatter(df.x,df.y,s=10,alpha=.25)\nfor g in [0,1]:\n grid=np.linspace(-band,0,60) if g==0 else np.linspace(0,band,60);plt.plot(grid,fit.predict(pd.DataFrame({'x':grid,'t':g})))\nplt.axvline(0,c='gray');plt.xlabel('Eşiğe uzaklık');plt.ylabel('Sonuç')", "id": "s115", "module": 28, "title": "Regresyon süreksizliği", "output": "{'yerel_n': 237, 'sicrama': np.float64(1.8505145267244167), 'HC1_CI': [1.3761987951340424, 2.324830258314791], 'gercek': 1.5}\n", "image": "advanced/s115.png", "notebook": "advanced/konu_29.ipynb", "script": "advanced/konu_29.py"}, "s116": {"question": "Tekrarlı bakış ve ön dönem bilgisi deneyi nasıl etkiler?", "reading": "Önceden planlı dört bakışı Bonferroni eşiğiyle oku; CUPED varyansını ayrı karşılaştır.", "limit": "Bu basit dört bakış düzeltmesi always-valid veya genel grup sıralı tasarım değildir. CUPED kovaryatı tedavi öncesi olmalı.", "task": "Etkiyi .15’ten 0’a indir; tek simülasyondan tip I hata oranı çıkarmamaya dikkat et.", "code": "n=800;pre=rng.normal(size=n);t=rng.binomial(1,.5,n);y=.15*t+.8*pre+rng.normal(size=n);theta=np.cov(y,pre,ddof=1)[0,1]/np.var(pre,ddof=1);adjusted=y-theta*(pre-pre.mean());looks=[200,400,600,800];p=[]\nfor k in looks:p.append(stats.ttest_ind(y[:k][t[:k]==1],y[:k][t[:k]==0],equal_var=False).pvalue)\nprint({'bakis_p':p,'planli_esik':.05/len(looks),'ham_varyans':np.var(y),'CUPED_varyans':np.var(adjusted),'theta':theta});plt.plot(looks,p,'o-');plt.axhline(.05/len(looks),c='tab:orange');plt.xlabel('Planlı bakış n');plt.ylabel('İki yönlü p')", "id": "s116", "module": 28, "title": "Sıralı deneyler ve varyans azaltma", "output": "{'bakis_p': [np.float64(0.06447387608549475), np.float64(0.0010567565716126737), np.float64(0.023325880684379748), np.float64(0.014167369198746234)], 'planli_esik': 0.0125, 'ham_varyans': np.float64(1.6273526233518292), 'CUPED_varyans': np.float64(1.0114659402379582), 'theta': np.float64(0.8008737990489679)}\n", "image": "advanced/s116.png", "notebook": "advanced/konu_29.ipynb", "script": "advanced/konu_29.py"}, "s117": {"question": "Sonlu partiden yerine koymadan seçince hata olasılığı nedir?", "reading": "Hipergeometrik dağılımı aynı oranlı binom yaklaşımıyla karşılaştır.", "limit": "Multinomial sabit n ve toplamı 1 olan kategoriler içindir; bağımsız ayrı binomların toplamı sabit değildir.", "task": "Örnekleme payını 10/100’den 60/100’e çıkar; sonlu evren farkını gör.", "code": "N,K,n=100,15,20;k=np.arange(n+1);hyper=stats.hypergeom(N,K,n).pmf(k);binom=stats.binom(n,K/N).pmf(k);counts=np.array([5,9,6]);p=np.array([.2,.5,.3]);print({'hiper_P_en_az_1':stats.hypergeom.sf(0,N,K,n),'multinomial_P_5_9_6':stats.multinomial.pmf(counts,n=20,p=p)})\nassert np.isclose(hyper.sum(),1);plt.plot(k,hyper,'o-',label='Hipergeometrik');plt.plot(k,binom,'o-',label='Binom yaklaşımı');plt.xlabel('Hata sayısı');plt.ylabel('P(X=k)');plt.legend()", "id": "s117", "module": 29, "title": "Hipergeometrik ve multinomial dağılımlar", "output": "{'hiper_P_en_az_1': np.float64(0.9738063082903304), 'multinomial_P_5_9_6': np.float64(0.03535537004999999)}\n", "image": "advanced/s117.png", "notebook": "advanced/konu_30.ipynb", "script": "advanced/konu_30.py"}, "s118": {"question": "Gamma hız ve ölçek tanımlarını karıştırırsam ne olur?", "reading": "Aynı şekil için scale=1/rate ilişkisini açık tut.", "limit": "Beta 0–1 parametrelerini, gamma pozitif büyüklükleri modeller; tek bir şekil tüm veri için yeterli değildir.", "task": "Gamma hızını 2’den 4’e çıkar; ortalama ve varyansın nasıl değiştiğini hesapla.", "code": "shape,rate=3.,2.;scale=1/rate;g=stats.gamma(a=shape,scale=scale);b=stats.beta(2,5);print({'gamma_ortalama':g.mean(),'gamma_varyans':g.var(),'gamma_P_X_2_alti':g.cdf(2),'beta_ortalama':b.mean()});x=np.linspace(.001,5,300);plt.plot(x,g.pdf(x),label='Gamma');xx=np.linspace(.001,.999,200);plt.plot(xx,b.pdf(xx),label='Beta');plt.xlabel('Değer');plt.ylabel('Yoğunluk');plt.legend()", "id": "s118", "module": 29, "title": "Beta ve gamma aileleri", "output": "{'gamma_ortalama': np.float64(1.5), 'gamma_varyans': np.float64(0.75), 'gamma_P_X_2_alti': np.float64(0.7618966944464556), 'beta_ortalama': np.float64(0.2857142857142857)}\n", "image": "advanced/s118.png", "notebook": "advanced/konu_30.ipynb", "script": "advanced/konu_30.py"}, "s119": {"question": "Henüz arızalanmamış birimi Weibull uyumuna nasıl dahil ederim?", "reading": "Sabit sansür zamanı altında yaşam eğrisiyle hazard biçimini ayır.", "limit": "Parametrik Weibull ve bağımsız sansür varsayılır; sansürü arıza saymak yanlıdır.", "task": "Sansür zamanını 18’den 10’a indir; tahmin ve gözlenen olay sayısını karşılaştır.", "code": "shape,scale=1.8,20.;life=stats.weibull_min.rvs(shape,scale=scale,size=300,random_state=rng);censor=18.;event=life<=censor;obs=np.minimum(life,censor);data=stats.CensoredData(uncensored=obs[event],right=obs[~event]);c,loc,s=stats.weibull_min.fit(data,floc=0);print({'olay_n':int(event.sum()),'sansur_n':int((~event).sum()),'uyum_sekil':c,'uyum_olcek':s,'gercek_sekil':shape,'gercek_olcek':scale})\nx=np.linspace(.01,40,200);plt.plot(x,stats.weibull_min.sf(x,c,scale=s),label='Uyum yaşam');plt.plot(x,stats.weibull_min.sf(x,shape,scale=scale),'--',label='Gerçek yaşam');plt.xlabel('Gün');plt.ylabel('S(t)');plt.legend()", "id": "s119", "module": 29, "title": "Weibull, hazard ve güvenilirlik", "output": "{'olay_n': 161, 'sansur_n': 139, 'uyum_sekil': np.float64(1.678654360886087), 'uyum_olcek': np.float64(21.12057042762909), 'gercek_sekil': 1.8, 'gercek_olcek': 20.0}\n", "image": "advanced/s119.png", "notebook": "advanced/konu_30.ipynb", "script": "advanced/konu_30.py"}, "s120": {"question": "ECDF ile yoğunluk tahmini neden farklı çizilir?", "reading": "ECDF birikimli payı, KDE alanı 1 olan yoğunluğu gösterir.", "limit": "KDE bant genişliğine ve sınır yanlılığına duyarlıdır; negatif alana sızma pozitif süre modeliyle çelişebilir.", "task": "bw_method=.2 yerine .6 yap; küçük tepelerin kaybolmasını yorumla.", "code": "x=rng.lognormal(1,.6,160);grid=np.linspace(0,15,300);kde=stats.gaussian_kde(x,bw_method=.2);sorted_x=np.sort(x);ecdf=np.arange(1,len(x)+1)/len(x);print({'n':len(x),'F_5':np.mean(x<=5),'KDE_P_0_5':kde.integrate_box_1d(0,5),'negatif_sizma':kde.integrate_box_1d(-np.inf,0)})\nfig,axes=plt.subplots(1,2,figsize=(9,3.5));axes[0].step(sorted_x,ecdf,where='post');axes[0].set(xlabel='Süre',ylabel='ECDF');axes[1].plot(grid,kde(grid));axes[1].set(xlabel='Süre',ylabel='KDE yoğunluğu');fig.tight_layout()", "id": "s120", "module": 29, "title": "Ampirik dağılım, ECDF ve yoğunluk tahmini", "output": "{'n': 160, 'F_5': np.float64(0.8625), 'KDE_P_0_5': np.float64(0.8596896165316013), 'negatif_sizma': np.float64(0.001968165534576482)}\n", "image": "advanced/s120.png", "notebook": "advanced/konu_30.ipynb", "script": "advanced/konu_30.py"}};